// Semantic comparison of two launchd XML plists. The carrier definition is generated by us, but any tool that
// re-serializes it (plutil, PlistBuddy, an editor) changes the bytes (tab indent, sorted keys) without changing the
// meaning. A byte comparison then reads that as "definition changed" and a healthy service gets a full
// bootout+bootstrap on every `start`. This is a deliberately small parser for the XML plist subset launchd jobs use
// (dict, array, string, key, true, false, integer, real); anything it does not understand makes the comparison
// return false, i.e. the caller falls back to the conservative "treat as different" behaviour.

type PlistValue = string | number | boolean | PlistValue[] | { [key: string]: PlistValue };

class Cursor {
  constructor(private readonly text: string, public pos = 0) {}
  eof(): boolean { return this.pos >= this.text.length; }
  skipSpace(): void { while (!this.eof() && /\s/.test(this.text[this.pos]!)) this.pos += 1; }
  startsWith(token: string): boolean { return this.text.startsWith(token, this.pos); }
  take(token: string): void {
    if (!this.startsWith(token)) throw new Error(`expected ${token} at ${this.pos}`);
    this.pos += token.length;
  }
  until(token: string): string {
    const end = this.text.indexOf(token, this.pos);
    if (end < 0) throw new Error(`missing ${token}`);
    const out = this.text.slice(this.pos, end);
    this.pos = end + token.length;
    return out;
  }
}

function decodeEntities(raw: string): string {
  return raw.replace(/&(#x[0-9a-fA-F]+|#[0-9]+|lt|gt|amp|quot|apos);/g, (_m, entity: string) => {
    switch (entity) {
      case "lt": return "<";
      case "gt": return ">";
      case "amp": return "&";
      case "quot": return "\"";
      case "apos": return "'";
      default: {
        const code = entity.startsWith("#x") ? Number.parseInt(entity.slice(2), 16) : Number.parseInt(entity.slice(1), 10);
        return String.fromCodePoint(code);
      }
    }
  });
}

function skipMisc(cursor: Cursor): void {
  for (;;) {
    cursor.skipSpace();
    if (cursor.startsWith("<!--")) { cursor.take("<!--"); cursor.until("-->"); continue; }
    if (cursor.startsWith("<?")) { cursor.take("<?"); cursor.until("?>"); continue; }
    if (cursor.startsWith("<!DOCTYPE")) { cursor.take("<!DOCTYPE"); cursor.until(">"); continue; }
    return;
  }
}

function parseElement(cursor: Cursor): PlistValue {
  skipMisc(cursor);
  cursor.take("<");
  const name = cursor.until(">");
  if (name.endsWith("/")) {
    const tag = name.slice(0, -1).trim();
    if (tag === "true") return true;
    if (tag === "false") return false;
    if (tag === "dict") return Object.create(null);
    if (tag === "array") return [];
    if (tag === "string") return "";
    throw new Error(`unsupported empty element ${tag}`);
  }
  switch (name) {
    case "string": return decodeEntities(cursor.until("</string>"));
    case "integer": return Number.parseInt(cursor.until("</integer>").trim(), 10);
    case "real": return Number.parseFloat(cursor.until("</real>").trim());
    case "true": cursor.until("</true>"); return true;
    case "false": cursor.until("</false>"); return false;
    case "array": {
      const items: PlistValue[] = [];
      for (;;) {
        skipMisc(cursor);
        if (cursor.startsWith("</array>")) { cursor.take("</array>"); return items; }
        items.push(parseElement(cursor));
      }
    }
    case "dict": {
      // No prototype: a key such as `__proto__` is then an ordinary entry and cannot corrupt the comparison.
      const entries: { [key: string]: PlistValue } = Object.create(null);
      for (;;) {
        skipMisc(cursor);
        if (cursor.startsWith("</dict>")) { cursor.take("</dict>"); return entries; }
        cursor.take("<key>");
        const key = decodeEntities(cursor.until("</key>"));
        // A repeated key is ambiguous (which value does launchd honour?): refuse to compare rather than let the
        // later one silently win. The caller then treats the definitions as different.
        if (key in entries) throw new Error(`duplicate key ${key}`);
        entries[key] = parseElement(cursor);
      }
    }
    default:
      throw new Error(`unsupported element ${name}`);
  }
}

export function parsePlist(text: string): PlistValue {
  const cursor = new Cursor(text);
  skipMisc(cursor);
  cursor.take("<plist");
  cursor.until(">");
  const value = parseElement(cursor);
  skipMisc(cursor);
  cursor.take("</plist>");
  return value;
}

function equalValues(left: PlistValue, right: PlistValue): boolean {
  if (Array.isArray(left) || Array.isArray(right)) {
    return Array.isArray(left) && Array.isArray(right) && left.length === right.length && left.every((item, index) => equalValues(item, right[index]!));
  }
  if (typeof left === "object" && typeof right === "object") {
    const leftKeys = Object.keys(left).sort();
    const rightKeys = Object.keys(right).sort();
    return leftKeys.length === rightKeys.length
      && leftKeys.every((key, index) => key === rightKeys[index] && equalValues(left[key]!, right[key]!));
  }
  return left === right;
}

/** True when both texts parse as plists with the same content (dict key order and whitespace are irrelevant). */
export function plistsSemanticallyEqual(left: string, right: string): boolean {
  if (left === right) return true;
  try {
    return equalValues(parsePlist(left), parsePlist(right));
  } catch {
    return false;
  }
}
